<?php $id=(int)($_GET['id']??0); $r=mysqli_fetch_assoc(mysqli_query($koneksi,"SELECT a.*,k.namakategori FROM alat a LEFT JOIN kategori k ON k.idkategori=a.idkategori WHERE a.idalat=$id")); ?><h2>Detail Sarana</h2><?php if(!empty($r['foto']) && $r['foto']!=='default.png'): ?><img src="assets/uploads/sarana/<?=htmlspecialchars($r['foto'])?>" alt="Foto sarana" style="max-width:280px;border-radius:12px" class="mb-3"><?php endif; ?><dl><dt>Nama</dt><dd><?=htmlspecialchars($r['namaalat'])?></dd><dt>Kategori</dt><dd><?=htmlspecialchars($r['namakategori']??'-')?></dd><dt>Jumlah</dt><dd><?=$r['jumlah']?></dd><dt>Kondisi</dt><dd><?=htmlspecialchars($r['kondisi'])?></dd><dt>Lokasi</dt><dd><?=htmlspecialchars($r['lokasi'])?></dd></dl>